-- 1. Las casillas
INSERT INTO sirve.casilla (id_seccion, id_distrito, clave, tipo, activa)
SELECT s.id, d.id, v.clave, v.tipo, true
  FROM carga_casilla v
  JOIN sirve.entidad e ON e.clave = '19'
  JOIN sirve.proceso_electoral p ON p.id_entidad = e.id AND p.anio = 2021
  JOIN sirve.municipio m ON m.id_entidad = e.id AND m.clave = v.municipio
  JOIN sirve.seccion s ON s.id_proceso = p.id AND s.id_municipio = m.id AND s.clave = v.seccion
  LEFT JOIN sirve.distrito d ON d.id_entidad = e.id AND d.tipo = 'LOCAL' AND d.clave = v.distrito
 WHERE NOT EXISTS (SELECT 1 FROM sirve.casilla k WHERE k.clave = v.clave);

-- 2. En qué elecciones se usa cada casilla
INSERT INTO sirve.casilla_eleccion (id_casilla, id_eleccion)
SELECT k.id, el.id
  FROM carga_casilla v
  JOIN sirve.casilla k ON k.clave = v.clave
  JOIN sirve.proceso_electoral p ON p.anio = 2021
       AND p.id_entidad = (SELECT id FROM sirve.entidad WHERE clave = '19')
  JOIN sirve.eleccion el ON el.id_proceso = p.id
       AND el.clave = ANY (string_to_array(v.elecciones, ','))
 WHERE NOT EXISTS (SELECT 1 FROM sirve.casilla_eleccion ce
                    WHERE ce.id_casilla = k.id AND ce.id_eleccion = el.id);

DROP TABLE carga_casilla;

-- 3. Comprobación
SELECT p.anio, count(*) AS casillas
  FROM sirve.casilla k
  JOIN sirve.seccion s ON s.id = k.id_seccion
  JOIN sirve.proceso_electoral p ON p.id = s.id_proceso
 GROUP BY p.anio ORDER BY p.anio;

SELECT p.anio, count(*) AS pares_casilla_eleccion
  FROM sirve.casilla_eleccion ce
  JOIN sirve.casilla k ON k.id = ce.id_casilla
  JOIN sirve.seccion s ON s.id = k.id_seccion
  JOIN sirve.proceso_electoral p ON p.id = s.id_proceso
 GROUP BY p.anio ORDER BY p.anio;
